'use client';
import { useRef, useState, type CSSProperties, type KeyboardEvent, type PointerEvent, type ReactNode } from 'react';
import { cx } from '../lib/cx';
import { useControllable } from '../lib/hooks';
import { Icon } from '../lib/icons';
import { Fold, Swap, Think } from '../lib/motion';
import '../designme.css';
import './design-tuner.css';

export interface TunerParam {
  /** Names the value and the CSS variable it sets on the preview, `--dm-<key>` */
  key: string;
  /** Shown beside the slider, like "Radius" */
  label: string;
  min: number;
  max: number;
  /** Where the slider starts when you don't pass values */
  value: number;
  /** Added after whole numbers, like "px". Leave it out for plain numbers */
  unit?: string;
  /** Shows and sets the value with this many decimals instead of rounding it, like 2 for a shadow strength */
  decimals?: number;
}

export interface DesignTunerProps {
  /** The sliders. Defaults to radius, padding, spacing and shadow for the sample card */
  params?: TunerParam[];
  /** The value of each slider by key. Leave it out to let the sliders keep their own */
  values?: Record<string, number>;
  defaultValues?: Record<string, number>;
  onValuesChange?: (values: Record<string, number>) => void;
  /** What is being tuned, like "Pricing card" */
  title?: string;
  /** Quiet line beside the title, like "Edited by you" or "Agent is tuning". It shimmers while `tuning` */
  status?: string;
  /** Key of the slider the agent is moving now; its value turns the accent colour */
  active?: string;
  /** The agent is tuning: the button thinks and stops taking clicks */
  tuning?: boolean;
  /** What the agent changed and why, a plain line with a spark above the footer */
  note?: ReactNode;
  /** The button's label, like "Tune with agent" or "Tune again" */
  actionLabel?: string;
  onTune?: () => void;
  /** What the sliders change. Gets the values and a style with a `--dm-<key>` variable for each one.
      Defaults to the sample pricing card from designme.dev */
  preview?: (values: Record<string, number>, vars: CSSProperties) => ReactNode;
  className?: string;
}

const PARAMS: TunerParam[] = [
  { key: 'rad', label: 'Radius', min: 0, max: 28, value: 16, unit: 'px' },
  { key: 'pad', label: 'Padding', min: 8, max: 32, value: 18, unit: 'px' },
  { key: 'gap', label: 'Spacing', min: 4, max: 24, value: 12, unit: 'px' },
  { key: 'sh', label: 'Shadow', min: 0, max: .2, value: .08, decimals: 2 }
];

const clamp = (p: TunerParam, v: number) => Math.max(p.min, Math.min(p.max, v));
const shown = (p: TunerParam, v: number) => p.decimals ? v.toFixed(p.decimals) : Math.round(v) + (p.unit ?? '');
const cssValue = (p: TunerParam, v: number) => p.decimals ? String(+v.toFixed(p.decimals)) : Math.round(v) + (p.unit ?? '');

/** The sample the site tunes: a pricing card that reads --dm-rad, --dm-pad, --dm-gap and --dm-sh */
function SampleCard({ vars }: { vars: CSSProperties }) {
  return (
    <div className="dm-dtx-card" style={vars}>
      <span className="dm-tag dm-b dm-dtx-tg">Pro</span>
      <div className="dm-dtx-pr"><b className="dm-num">$24</b><span className="dm-muted">per editor, monthly</span></div>
      <div className="dm-dtx-li">{['Unlimited frames', 'Agent reviews', 'Shared tokens'].map(t => <span key={t}><Icon name="check" size="xs" />{t}</span>)}</div>
      <button type="button" className="dm-pill dm-accent dm-dtx-cta">Start free trial</button>
    </div>
  );
}

function Slider({ param, value, hot, onChange }: { param: TunerParam; value: number; hot: boolean; onChange: (v: number) => void }) {
  const [drag, setDrag] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  const pct = (value - param.min) / (param.max - param.min) * 100;
  const at = (e: PointerEvent) => { const b = ref.current!.getBoundingClientRect(); onChange(clamp(param, param.min + (param.max - param.min) * Math.max(0, Math.min(1, (e.clientX - b.left) / b.width)))); };
  const key = (e: KeyboardEvent) => {
    const dir = ({ ArrowRight: 1, ArrowUp: 1, ArrowLeft: -1, ArrowDown: -1 } as Record<string, number>)[e.key]; if (!dir) return;
    e.preventDefault(); onChange(clamp(param, value + dir * (param.decimals ? Math.pow(10, -param.decimals) : 1)));
  };
  return (
    <div className={cx('dm-dtx-r', hot && 'dm-hot')}>
      <span>{param.label}</span>
      <div ref={ref} className={cx('dm-dtx-sl', drag && 'dm-drag')} role="slider" tabIndex={0} aria-label={param.label}
        aria-valuemin={param.min} aria-valuemax={param.max} aria-valuenow={param.decimals ? +value.toFixed(param.decimals) : Math.round(value)} aria-valuetext={shown(param, value)}
        onPointerDown={e => { e.currentTarget.setPointerCapture(e.pointerId); setDrag(true); at(e); }}
        onPointerMove={e => { if (drag) at(e); }}
        onPointerUp={() => setDrag(false)} onPointerCancel={() => setDrag(false)} onKeyDown={key}>
        <span className="dm-f" style={{ width: pct + '%' }} /><span className="dm-k" style={{ left: pct + '%' }} />
      </div>
      <span className="dm-v dm-num">{shown(param, value)}</span>
    </div>
  );
}

/** A live preview beside a few sliders, with a button that hands the tuning to the agent. */
export function DesignTuner({ params = PARAMS, values, defaultValues, onValuesChange, title = 'Pricing card', status = 'Edited by you', active, tuning = false, note,
  actionLabel = 'Tune with agent', onTune, preview, className }: DesignTunerProps) {
  const [vals, setVals] = useControllable(values, defaultValues ?? Object.fromEntries(params.map(p => [p.key, p.value])), onValuesChange);
  const valueOf = (p: TunerParam) => clamp(p, vals[p.key] ?? p.value);
  const vars = Object.fromEntries(params.map(p => ['--dm-' + p.key, cssValue(p, valueOf(p))])) as CSSProperties;
  return (
    // the site lays this out by the width of its card, so the box around it is the container its query measures
    <div data-dm="" className={cx('dm-dtx-box', className)} style={{ containerType: 'inline-size', width: '100%' }}>
      <div className="dm-dtx">
        <div className="dm-dtx-prev">{preview ? preview(Object.fromEntries(params.map(p => [p.key, valueOf(p)])), vars) : <SampleCard vars={vars} />}</div>
        <div className="dm-dtx-insp dm-panel">
          {/* while the agent tunes, the status shimmers as every loader's words do */}
          <div className="dm-dtx-ih"><b>{title}</b><Swap className={cx('dm-muted dm-dtx-st', tuning && 'dm-shim')}>{status}</Swap></div>
          <div className="dm-dtx-rows">
            {params.map(p => <Slider key={p.key} param={p} value={valueOf(p)} hot={active === p.key} onChange={v => setVals({ ...vals, [p.key]: v })} />)}
          </div>
          {/* it folds open, so the inspector and the preview beside it ease to their new height */}
          <Fold open={!!note} className="dm-dtx-nf"><div className="dm-dtx-note"><Icon name="spark" size="xs" /><span>{note}</span></div></Fold>
          <div className="dm-dtx-f">
            <button type="button" className={cx('dm-pill dm-primary dm-sm dm-dtx-go', tuning && 'dm-busy')} aria-busy={tuning} onClick={() => { if (!tuning) onTune?.(); }}>
              {tuning ? <><Think />Tuning</> : <><Icon name="wand" size="xs" />{actionLabel}</>}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Design tuner ---------- */
/* the component being tuned on the left, its inspector on the right: the component's name and who changed it last in the head,
   a slider for each setting, what the agent changed as a plain line once it has tuned, and Tune with agent in the footer under
   a hairline. Both panels are as tall as each other; the footer sits at the inspector's foot */
.dm-dtx{display:grid;grid-template-columns:1fr 280px;gap:14px;align-items:stretch}
@media (max-width:720px){.dm-dtx{grid-template-columns:1fr}}
@container (max-width:600px){.dm-dtx{grid-template-columns:1fr}.dm-dtx-prev{min-height:240px}}
.dm-dtx-prev{border-radius:calc(18px * var(--dm-rk));background:var(--dm-chip);display:grid;place-items:center;padding:var(--dm-s-6);min-height:300px;min-width:0}
.dm-dtx-card{--dm-rad:16px;--dm-pad:18px;--dm-gap:12px;--dm-sh:.08;width:min(250px,100%);background:var(--dm-surface);border-radius:var(--dm-rad);padding:var(--dm-pad);display:flex;flex-direction:column;gap:var(--dm-gap);box-shadow:0 1px 2px rgba(0,0,0,var(--dm-sh)),0 8px 24px rgba(0,0,0,calc(var(--dm-sh) * .8))}
.dm-dtx-tg{align-self:flex-start}
.dm-dtx-pr{display:flex;align-items:baseline;gap:6px}
.dm-dtx-pr b{font-size:14px;font-weight:500;letter-spacing:-.02em}
.dm-dtx-pr span{font-size:12px}
.dm-dtx-li{display:flex;flex-direction:column;gap:6px;font-size:13px;color:var(--dm-fg2)}
.dm-dtx-li span{display:flex;align-items:center;gap:7px}
.dm-dtx-li svg{color:var(--dm-accent-fg,var(--dm-accent))}
.dm-dtx-cta{width:100%;border-radius:calc(var(--dm-rad) * .6)}
.dm-dtx-insp{padding:var(--dm-s-4);display:flex;flex-direction:column;--dm-dg:var(--dm-s-3);gap:var(--dm-dg);min-width:0}
/* the head: the name and, on its baseline, who changed it last (the words shimmer while the agent tunes, as every loader's do) */
.dm-dtx-ih{display:flex;align-items:baseline;justify-content:space-between;gap:var(--dm-s-3);font-size:13.5px;line-height:20px}
.dm-dtx-ih b{font-weight:500}
.dm-dtx-st{font-size:12px;line-height:18px;white-space:nowrap}
.dm-dtx-st .dm-shim{font-size:inherit}
.dm-dtx-rows{display:flex;flex-direction:column;gap:var(--dm-s-3);flex:1 0 auto}
.dm-dtx-r{display:grid;grid-template-columns:62px 1fr 40px;align-items:center;gap:var(--dm-s-3);font-size:12.5px;color:var(--dm-fg2)}
.dm-dtx-r .dm-v{text-align:right;color:var(--dm-fg);font-size:12px}
.dm-dtx-r.dm-hot .dm-v{color:var(--dm-accent-fg,var(--dm-accent))}
.dm-dtx-sl{position:relative;height:22px;display:flex;align-items:center;cursor:pointer;touch-action:none}
.dm-dtx-sl::before{content:"";position:absolute;left:0;right:0;height:4px;border-radius:2px;background:var(--dm-rail)}
.dm-dtx-sl .dm-f{position:absolute;left:0;height:4px;border-radius:2px;background:var(--dm-accent-mark,var(--dm-accent))}
.dm-dtx-sl .dm-k{position:absolute;width:14px;height:14px;margin-left:-7px;border-radius:50%;background:#fff;box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent),0 1px 3px rgba(0,0,0,.18);transition:transform .2s}
.dm-dtx-sl.dm-drag .dm-k,.dm-dtx-sl:focus-visible .dm-k{transform:scale(1.15)}
@media (hover:hover) and (pointer:fine){.dm-dtx-sl:hover .dm-k{transform:scale(1.15)}}
.dm-dtx-sl:focus-visible{outline-offset:4px}
/* what the agent changed: a plain line with its spark, no box (notes are plain text) */
/* (it folds open, so the inspector, and the stage beside it, ease to their new height instead of jumping; the gap above it is
   inside the fold) */
.dm-dtx-nf{margin-top:calc(-1 * var(--dm-dg))}
.dm-dtx-nf>div>.dm-dtx-note{margin-top:var(--dm-dg)}
.dm-dtx-note{display:grid;grid-template-columns:16px minmax(0,1fr);column-gap:var(--dm-s-2);font-size:12.5px;line-height:18px;color:var(--dm-fg2)}
.dm-dtx-note>svg{margin-top:1px;color:var(--dm-accent-fg,var(--dm-accent))}
/* the footer: Tune with agent on the right, 16px under the hairline and 16px above the card's edge */
.dm-dtx-f{display:flex;justify-content:flex-end;padding-top:var(--dm-s-4);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-dtx-go.dm-busy{pointer-events:none}
/* Clean: the inspector has an off-white head and foot strip, 16px round their contents; the stage the component sits on has
   Clean's card corners and a grey a step stronger than the page's, so it shows on it; the sliders take Clean's track and knob */
:root[data-style="clean"] .dm-dtx-prev,:root [data-style="clean"] .dm-dtx-prev,:root [data-style="clean"].dm-dtx-prev{border-radius:var(--dm-r-card);background:var(--dm-hover)}
:root[data-style="clean"] .dm-dtx-insp,:root [data-style="clean"] .dm-dtx-insp,:root [data-style="clean"].dm-dtx-insp{padding:0 16px;--dm-dg:16px;overflow:clip}
:root[data-style="clean"] .dm-dtx-ih,:root [data-style="clean"] .dm-dtx-ih,:root [data-style="clean"].dm-dtx-ih{margin:0 -16px;padding:var(--dm-strip-y) 16px;background:var(--dm-strip);border-bottom:1px solid var(--dm-line)}
:root[data-style="clean"] .dm-dtx-ih>*,:root [data-style="clean"] .dm-dtx-ih>*,:root [data-style="clean"].dm-dtx-ih>*{line-height:28px}
:root[data-style="clean"] .dm-dtx-f,:root [data-style="clean"] .dm-dtx-f,:root [data-style="clean"].dm-dtx-f{margin:0 -16px;padding:var(--dm-strip-y) 16px;background:var(--dm-strip);border-top-color:var(--dm-line)}
:root[data-style="clean"] .dm-dtx-sl::before,:root [data-style="clean"] .dm-dtx-sl::before,:root [data-style="clean"].dm-dtx-sl::before{height:6px;border-radius:3px;box-shadow:var(--dm-track-ring)}
:root[data-style="clean"] .dm-dtx-sl .dm-f,:root [data-style="clean"] .dm-dtx-sl .dm-f,:root [data-style="clean"].dm-dtx-sl .dm-f{height:6px;border-radius:3px}
:root[data-style="clean"] .dm-dtx-sl .dm-k,:root [data-style="clean"] .dm-dtx-sl .dm-k,:root [data-style="clean"].dm-dtx-sl .dm-k{width:16px;height:16px;margin-left:-8px;background:var(--dm-knob);box-shadow:var(--dm-knob-shadow);transition:transform var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .dm-dtx-r .dm-v,:root [data-style="clean"] .dm-dtx-r .dm-v,:root [data-style="clean"].dm-dtx-r .dm-v{transition:color var(--dm-t-fast) var(--dm-ease)}
